import { test, expect } from '@playwright/test';

test.describe('Product Search by Keyword', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products');
  });

  test('should display instant search results as user types a keyword', async ({ page }) => {
    // Verify search input is visible and accessible
    const searchInput = page.getByPlaceholder('Search products...');
    await expect(searchInput).toBeVisible();

    // Verify search button is visible
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();

    // Type keyword into search input
    await searchInput.fill('laptop');

    // Wait for instant results to appear
    await page.waitForResponse(response => 
      response.url().includes('/api/products/search') && response.status() === 200
    );

    // Verify search results container is visible
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    // Verify results list is populated
    const resultItems = page.getByTestId('product-item');
    await expect(resultItems).toHaveCount(2);

    // Verify results contain the keyword
    const firstResult = page.getByText('laptop');
    await expect(firstResult).toBeVisible();

    // Verify result items have product names
    const resultNames = page.getByRole('heading', { name: /laptop/i });
    await expect(resultNames).toHaveCount(2);
  });

  test('should handle no results found and display appropriate message', async ({ page }) => {
    // Type a non-existent keyword
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('xyz123nonexistentproduct');

    // Wait for API response
    await page.waitForResponse(response => 
      response.url().includes('/api/products/search') && response.status() === 200
    );

    // Verify no results message is displayed
    const noResultsMessage = page.getByText('No products found');
    await expect(noResultsMessage).toBeVisible();

    // Verify results container is visible but empty
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    const resultItems = page.getByTestId('product-item');
    await expect(resultItems).toHaveCount(0);

    // Verify search input still retains the value
    await expect(searchInput).toHaveValue('xyz123nonexistentproduct');

    // Verify user can clear the search input
    const clearButton = page.getByRole('button', { name: /clear/i });
    await clearButton.click();
    await expect(searchInput).toHaveValue('');
  });
});
